{
  "name": "EmStat Pico微型恒电位仪模块",
  "name_en": "EmStat Pico potentiostat module",
  "manufacturer": "PalmSens",
  "description": "这是一款小型电化学测量模块，用于控制电极电位并采集电化学响应，可通过MethodSCRIPT执行测试流程。它常用于实验室电化学实验、传感器开发以及便携式分析仪器集成。",
  "description_en": "This is a compact electrochemical measurement module used to control electrode potential and acquire electrochemical responses, with test procedures executed through MethodSCRIPT. It is commonly used for laboratory electrochemistry, sensor development, and integration into portable analyzers.",
  "tag_hints": [
    "electrochemistry",
    "potentiostat module",
    "MethodSCRIPT",
    "electrochemical sensing",
    "portable analyzer",
    "embedded instrumentation"
  ],
  "actions": [
    {
      "action_name": "auto-write",
      "description": "向仪器写入一行ASCII命令文本。",
      "description_en": "Write one line of ASCII command text to the instrument."
    },
    {
      "action_name": "auto-writelines",
      "description": "向仪器连续写入多行命令文本。",
      "description_en": "Write multiple lines of command text to the instrument."
    },
    {
      "action_name": "auto-readline",
      "description": "从仪器读取一行响应文本。",
      "description_en": "Read one line of response text from the instrument."
    },
    {
      "action_name": "auto-readlines_until_end",
      "description": "持续读取仪器返回内容，直到接收到结束空行为止。",
      "description_en": "Read response lines from the instrument until an empty terminating line is received."
    },
    {
      "action_name": "auto-load_mscript_from_flash",
      "description": "将仪器闪存中的MethodSCRIPT加载到运行内存。",
      "description_en": "Load the MethodSCRIPT stored in instrument flash into working memory."
    },
    {
      "action_name": "auto-run_mscript_from_flash",
      "description": "加载并执行仪器闪存中的MethodSCRIPT。",
      "description_en": "Load and execute the MethodSCRIPT stored in instrument flash."
    },
    {
      "action_name": "auto-send_script",
      "description": "将脚本文件发送到仪器。",
      "description_en": "Send a script file to the instrument."
    },
    {
      "action_name": "auto-abort_and_sync",
      "description": "中止当前运行的脚本并使仪器恢复到同步的可用状态。",
      "description_en": "Abort the currently running script and return the instrument to a synchronized ready state."
    }
  ]
}

